const { accessSync } = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath) throw new Error('Missing INPUT_PATH');
if (!outputPath) throw new Error('Missing OUTPUT_PATH');
try { accessSync(inputPath); } catch { throw new Error('Input file not found'); }
globalThis.inputPath = inputPath;
globalThis.outputPath = outputPath;

const { execFile } = await import('node:child_process');
const { join } = await import('node:path');
const scriptPath = join(process.cwd(), 'node_modules', '@aspirio/topdf', 'index.js');
await new Promise((resolve, reject) => {
  execFile('node', [scriptPath, '-i', globalThis.inputPath, '-o', globalThis.outputPath], (error, stdout, stderr) => {
    if (error) reject(error);
    else resolve();
  });
});
globalThis.pdfPath = globalThis.outputPath;
